// Fictional sample. Replace the CSV and field mappings before practical use.
// This code creates one input item; it does not contact any service.
return [{ json: {
  "csv_text": "variant_id,description\ngid://shopify/ProductVariant/1001,Machine washable\n",
  "fields": [
    {
      "column": "description",
      "namespace": "custom",
      "key": "care_instructions",
      "type": "multi_line_text_field"
    }
  ],
  "identifier_mode": "variant_id",
  "identifier_column": "variant_id",
  "write_policy": "create_only",
  "delimiter": ","
} }];

// Inspect the completed report; HTTP success alone is not validation success.
const items = $input.all();
if (items.length !== 1) throw new Error('Expected one HTTP response.');
const response = items[0].json;
if (!Number.isInteger(response.statusCode) || response.statusCode < 200 || response.statusCode >= 300) {
  throw new Error('The Apify request did not return a successful HTTP status.');
}
if (!Array.isArray(response.body) || response.body.length !== 1) {
  throw new Error('Expected exactly one complete report. Check the Apify run before retrying.');
}
const report = response.body[0];
if (!report || report.schema_version !== '1.0' || !['ready', 'blocked', 'no_changes'].includes(report.status)
    || !Array.isArray(report.issues) || !Array.isArray(report.batches) || !report.summary
    || report.remote_requests !== 0 || report.definition_constraints_verified !== false) {
  throw new Error('Unexpected planner report. Review the run manually.');
}
const counts = report.summary;
for (const key of ['planned_operations', 'batch_count', 'error_count']) {
  if (!Number.isInteger(counts[key]) || counts[key] < 0) throw new Error('Invalid report counters.');
}
if (counts.batch_count !== report.batches.length) throw new Error('Inconsistent batch count.');
if (report.status === 'ready') {
  if (counts.error_count !== 0 || counts.planned_operations < 1 || report.batches.length < 1) {
    throw new Error('The ready report is inconsistent. Do not use its requests.');
  }
  let operations = 0;
  for (const batch of report.batches) {
    const request = batch && batch.request;
    const metafields = request && request.variables && request.variables.metafields;
    if (!request || typeof request.query !== 'string' || request.query.length === 0
        || !Array.isArray(metafields) || metafields.length < 1 || metafields.length > 25) {
      throw new Error('Invalid request batch. Do not use its requests.');
    }
    operations += metafields.length;
  }
  if (operations !== counts.planned_operations) throw new Error('Inconsistent operation count.');
} else {
  if (report.batches.length !== 0 || counts.planned_operations !== 0
      || (report.status === 'blocked' && counts.error_count < 1)
      || (report.status === 'no_changes' && counts.error_count !== 0)) {
    throw new Error('A non-ready report contains inconsistent results. Do not use its requests.');
  }
}
return [{ json: {
  ...report,
  next_action: report.status === 'ready' ? 'review_requests' : report.status === 'blocked' ? 'correct_input' : 'nothing_to_apply',
  shopify_write_authorized: false
} }];
